@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=true","ticket.mock-payments.enabled=true","ticket.issuance.enabled=true","ticket.check-in.enabled=true","ticket.admission-window.enabled=true","ticket.admission.enabled=false","ticket.expiry.enabled=false","ticket.stock-return-recovery.enabled=false"})
@AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class TicketIntegrationTest {
 @Autowired AdmissionWindowService windows;@Autowired TicketService tickets;@Autowired OrderService orders;@Autowired PaymentService payments;@Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired JdbcTemplate db;@Autowired PlatformTransactionManager transactions;@Autowired ObjectMapper json;@Autowired MockMvc mvc;
 String manager="tickets-manager-"+UUID.randomUUID(),viewer="tickets-viewer-"+UUID.randomUUID();
 record Fixture(Principal customer,String token,UUID session,UUID ticket,Order order){}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));for(var s:List.of(manager,viewer))db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),s,"synthetic unused hash",s.equals(manager)?"MANAGER":"VIEWER");}
 Fixture fixture(int quantity){var c=customers.register("t-"+UUID.randomUUID().toString().substring(0,30),"合成票券",UUID.randomUUID().toString());var p=customers.authenticate(c.token()).orElseThrow();var end=OffsetDateTime.now().plusHours(1);var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"tickets-"+UUID.randomUUID(),"票券合成活動","不收款","合成場地"));var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"入場場次",end.plusDays(1),OffsetDateTime.now().minusHours(1),end));windows.configure(manager,s.id(),new AdmissionWindowModels.Configure(UUID.randomUUID(),0,Instant.now().minusSeconds(3600).truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString(),Instant.now().plusSeconds(3600).truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString()));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般票",1200,10,10));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);var o=orders.place(p,new Place(UUID.randomUUID(),t.id(),quantity,1,1200*quantity));return new Fixture(p,c.token(),s.id(),t.id(),o);}
 Order pay(Fixture f,String scenario){var o=payments.start(f.customer(),f.order().id(),new Pay(UUID.randomUUID(),1,f.order().totalTwd(),scenario));return payments.reconcile(f.customer(),o.id(),o.payment().id(),new Reconcile(UUID.randomUUID()));}
 Bundle issue(Fixture f){var o=pay(f,"SUCCESS");return tickets.issue(f.customer(),o.id(),new Issue(UUID.randomUUID(),o.version()));}
 CheckIn check(Fixture f,CustomerTicket t){return new CheckIn(UUID.randomUUID(),t.code(),f.session(),t.version());}
 Revoke revoke(Fixture f,CustomerTicket t){return new Revoke(UUID.randomUUID(),t.id(),f.session(),t.version(),"LOST_CODE");}
 void problem(int status,Runnable run){assertEquals(status,assertThrows(Problem.class,run::run).status);}
 int count(String table,UUID order){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE order_id=?",Integer.class,order);}
 String source(Fixture f){return db.queryForObject("SELECT jsonb_build_array(to_jsonb(o),to_jsonb(t),(SELECT jsonb_agg(to_jsonb(x) ORDER BY phase) FROM order_inventory_event x WHERE order_id=o.id),(SELECT jsonb_agg(to_jsonb(x)) FROM payment_inventory_event x WHERE order_id=o.id),(SELECT jsonb_agg(to_jsonb(x) ORDER BY revision) FROM stock_revision x WHERE ticket_id=t.id))::text FROM ticket_order o JOIN ticket_type t ON t.id=o.ticket_id WHERE o.id=?",String.class,f.order().id());}
 @Test void paidQuantityIssuesSecureUnitsOnceWithoutStockMutation(){var f=fixture(2);var paid=pay(f,"SUCCESS");var before=source(f);var b=new Issue(UUID.randomUUID(),paid.version());var issued=tickets.issue(f.customer(),paid.id(),b);assertEquals(2,issued.tickets().size());assertNotEquals(issued.tickets().get(0).code(),issued.tickets().get(1).code());assertTrue(issued.tickets().stream().allMatch(t->t.code().matches("[A-Za-z0-9_-]{43}")&&t.version()==1&&t.state().equals("ACTIVE")));assertEquals(issued,tickets.issue(f.customer(),paid.id(),b));assertEquals(before,source(f));assertEquals(1,count("ticket_issuance_audit",paid.id()));assertEquals(2,count("issued_ticket",paid.id()));}
 @Test void unverifiedPaymentAndLateSuccessCannotIssue(){var pending=fixture(1);problem(409,()->tickets.issue(pending.customer(),pending.order().id(),new Issue(UUID.randomUUID(),1)));var declined=fixture(1);var no=pay(declined,"DECLINED");problem(409,()->tickets.issue(declined.customer(),no.id(),new Issue(UUID.randomUUID(),no.version())));var late=fixture(1);var started=payments.start(late.customer(),late.order().id(),new Pay(UUID.randomUUID(),1,1200,"SUCCESS"));orders.cancel(late.customer(),started.id(),new Cancel(UUID.randomUUID(),started.version()));var reviewed=payments.reconcile(late.customer(),started.id(),started.payment().id(),new Reconcile(UUID.randomUUID()));problem(409,()->tickets.issue(late.customer(),reviewed.id(),new Issue(UUID.randomUUID(),reviewed.version())));assertEquals(0,count("issued_ticket",reviewed.id()));}
 @Test void paidReviewRequiresManualResolutionAndCannotIssue(){var f=fixture(1);var o=pay(f,"SUCCESS");extraReview(f,o);problem(409,()->tickets.issue(f.customer(),o.id(),new Issue(UUID.randomUUID(),orders.detail(f.customer(),o.id()).version())));assertEquals(0,count("ticket_issuance",o.id()));}
 void extraReview(Fixture f,Order paid){db.update("INSERT INTO mock_payment_receipt(event_id,attempt_id,outcome,amount,currency) VALUES(?,?,'SUCCESS',?,'TWD')",UUID.randomUUID(),paid.payment().id(),paid.totalTwd());payments.reconcile(f.customer(),paid.id(),paid.payment().id(),new Reconcile(UUID.randomUUID()));}
 @Test void ownerExactBodyQuoteAndCrossActionAreBound(){var f=fixture(1);var o=pay(f,"SUCCESS");var other=fixture(1);problem(404,()->tickets.issue(other.customer(),o.id(),new Issue(UUID.randomUUID(),3)));problem(404,()->tickets.read(other.customer(),o.id()));problem(409,()->tickets.issue(f.customer(),o.id(),new Issue(UUID.randomUUID(),2)));var b=new Issue(UUID.randomUUID(),3);tickets.issue(f.customer(),o.id(),b);problem(409,()->tickets.issue(f.customer(),o.id(),new Issue(b.requestId(),4)));problem(409,()->orders.cancel(f.customer(),o.id(),new Cancel(b.requestId(),3)));problem(409,()->tickets.issue(f.customer(),o.id(),new Issue(UUID.randomUUID(),3)));}
 @Test void concurrentOriginalIssuanceReturnsSameCodes()throws Exception{var f=fixture(2);var o=pay(f,"SUCCESS");var b=new Issue(UUID.randomUUID(),3);try(var pool=Executors.newFixedThreadPool(6)){var tasks=new ArrayList<Callable<Bundle>>();for(int i=0;i<6;i++)tasks.add(()->tickets.issue(f.customer(),o.id(),b));Bundle first=null;for(var r:pool.invokeAll(tasks)){var v=r.get();if(first==null)first=v;else assertEquals(first,v);}}assertEquals(2,count("issued_ticket",o.id()));}
 @Test void competingNewIssuanceIdsCannotIssueTwice()throws Exception{var f=fixture(1);pay(f,"SUCCESS");try(var pool=Executors.newFixedThreadPool(4)){var tasks=new ArrayList<Callable<Boolean>>();for(int i=0;i<4;i++)tasks.add(()->{try{tickets.issue(f.customer(),f.order().id(),new Issue(UUID.randomUUID(),3));return true;}catch(Problem p){assertEquals("ISSUANCE_EXISTS",p.code);return false;}});int ok=0;for(var r:pool.invokeAll(tasks))if(r.get())ok++;assertEquals(1,ok);}assertEquals(1,count("issued_ticket",f.order().id()));}
 @Test void flagsOffReadAndExactReplayButRefuseNewWrites(){var f=fixture(1);pay(f,"SUCCESS");var b=new Issue(UUID.randomUUID(),3);var bundle=tickets.issue(f.customer(),f.order().id(),b);var off=new TicketService(db,json,false,false);var tx=new TransactionTemplate(transactions);assertEquals(bundle.tickets(),tx.execute(s->off.issue(f.customer(),f.order().id(),b)).tickets());assertFalse(tx.execute(s->off.read(f.customer(),f.order().id())).issuanceEnabled());problem(409,()->tx.execute(s->off.checkIn(manager,check(f,bundle.tickets().getFirst()))));var command=check(f,bundle.tickets().getFirst());var receipt=tickets.checkIn(manager,command);assertEquals(receipt,tx.execute(s->off.checkIn(manager,command)));}
 @Test void disabledOrLoggedOutCustomerCannotReadBearerOrIssue(){var f=fixture(1);issue(f);db.update("UPDATE customer_account SET enabled=false WHERE id=?",f.customer().id());problem(401,()->tickets.read(f.customer(),f.order().id()));problem(401,()->tickets.issue(f.customer(),f.order().id(),new Issue(UUID.randomUUID(),3)));var b=fixture(1);db.update("DELETE FROM customer_session WHERE token_hash=?",b.customer().sessionHash());problem(401,()->tickets.read(b.customer(),b.order().id()));}
 @Test void checkInReplaysOneAdmissionAndNoBearerInStaffJson()throws Exception{var f=fixture(1);var ticket=issue(f).tickets().getFirst();var before=source(f);var c=check(f,ticket);var result=tickets.checkIn(manager,c);assertEquals("CHECKED_IN",result.ticket().state());assertEquals(result,tickets.checkIn(manager,c));assertEquals(1,tickets.audit(viewer,ticket.id(),1,20).total());assertFalse(json.writeValueAsString(result).contains(ticket.code()));assertFalse(json.writeValueAsString(tickets.list(viewer,f.session(),1,20)).contains(ticket.code()));assertEquals(before,source(f));problem(409,()->tickets.checkIn(manager,check(f,ticket)));problem(409,()->tickets.revoke(manager,revoke(f,ticket)));problem(409,()->tickets.checkIn(manager,new CheckIn(c.requestId(),c.code(),UUID.randomUUID(),1)));}
 @Test void wrongSessionUnknownCodeAndViewerRefuseWithoutMutation(){var f=fixture(1);var t=issue(f).tickets().getFirst();problem(409,()->tickets.inspect(manager,new Inspect(t.code(),UUID.randomUUID())));problem(409,()->tickets.checkIn(manager,new CheckIn(UUID.randomUUID(),t.code(),UUID.randomUUID(),1)));problem(404,()->tickets.inspect(manager,new Inspect("X".repeat(43),f.session())));problem(403,()->tickets.inspect(viewer,new Inspect(t.code(),f.session())));problem(403,()->tickets.checkIn(viewer,check(f,t)));assertEquals("ACTIVE",tickets.read(f.customer(),f.order().id()).tickets().getFirst().state());}
 @Test void concurrentCheckInsPermitOneSuccess()throws Exception{var f=fixture(1);var t=issue(f).tickets().getFirst();try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<Boolean>>();for(int i=0;i<6;i++)jobs.add(()->{try{tickets.checkIn(manager,check(f,t));return true;}catch(Problem p){assertEquals("TICKET_TERMINAL",p.code);return false;}});int ok=0;for(var r:pool.invokeAll(jobs))if(r.get())ok++;assertEquals(1,ok);}assertEquals(1,tickets.audit(viewer,t.id(),1,20).total());}
 @Test void checkInAndRevocationRaceHasOneTerminalAudit()throws Exception{var f=fixture(1);var t=issue(f).tickets().getFirst();var before=source(f);try(var pool=Executors.newFixedThreadPool(2)){Callable<Boolean> in=()->{try{tickets.checkIn(manager,check(f,t));return true;}catch(Problem p){assertEquals(409,p.status);return false;}},out=()->{try{tickets.revoke(manager,revoke(f,t));return true;}catch(Problem p){assertEquals(409,p.status);return false;}};int ok=0;for(var r:pool.invokeAll(List.of(in,out)))if(r.get())ok++;assertEquals(1,ok);}assertEquals(1,tickets.audit(viewer,t.id(),1,20).total());assertEquals(before,source(f));}
 @Test void paymentReviewAfterIssuanceBlocksAdmissionButAllowsUnusedRevocation(){var f=fixture(2);var b=issue(f);var o=orders.detail(f.customer(),f.order().id());extraReview(f,o);var t=b.tickets().getFirst();assertFalse(tickets.inspect(manager,new Inspect(t.code(),f.session())).eligible());problem(409,()->tickets.checkIn(manager,check(f,t)));var before=source(f);var c=revoke(f,t);var r=tickets.revoke(manager,c);assertEquals("REVOKED",r.ticket().state());assertEquals(r,tickets.revoke(manager,c));assertEquals(before,source(f));assertEquals(b.tickets().get(1).code(),tickets.read(f.customer(),o.id()).tickets().get(1).code());}
 @Test void issuanceAuditFailureRollsBackEntireBatchAndOriginalRetry(){var f=fixture(2);pay(f,"SUCCESS");var b=new Issue(UUID.randomUUID(),3);db.execute("ALTER TABLE ticket_issuance_audit ADD CONSTRAINT e1_issue_fault CHECK(order_id<>'"+f.order().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->tickets.issue(f.customer(),f.order().id(),b));assertEquals(0,count("issued_ticket",f.order().id()));assertEquals(0,count("ticket_issuance",f.order().id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM order_command WHERE customer_id=? AND request_id=?",Integer.class,f.customer().id(),b.requestId()));}finally{db.execute("ALTER TABLE ticket_issuance_audit DROP CONSTRAINT e1_issue_fault");}assertEquals(2,tickets.issue(f.customer(),f.order().id(),b).tickets().size());}
 @Test void admissionAuditFailureRollsBackUseAndOriginalRetry(){var f=fixture(1);var t=issue(f).tickets().getFirst();var c=check(f,t);db.execute("ALTER TABLE ticket_admission_audit ADD CONSTRAINT e1_admit_fault CHECK(ticket_id<>'"+t.id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->tickets.checkIn(manager,c));assertEquals("ACTIVE",tickets.read(f.customer(),f.order().id()).tickets().getFirst().state());assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_admission_command WHERE request_id=?",Integer.class,c.requestId()));}finally{db.execute("ALTER TABLE ticket_admission_audit DROP CONSTRAINT e1_admit_fault");}assertEquals("CHECKED_IN",tickets.checkIn(manager,c).ticket().state());}
 @Test void partialIssuanceCannotCommit(){var f=fixture(2);pay(f,"SUCCESS");UUID r=UUID.randomUUID();assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->new TransactionTemplate(transactions).execute(s->{db.update("INSERT INTO order_command VALUES(?,?,'ISSUE',?,?,clock_timestamp())",f.customer().id(),r,"0".repeat(64),f.order().id());db.update("INSERT INTO ticket_issuance(order_id,customer_id,request_id,order_version,quantity,payment_event_id) SELECT id,customer_id,?,version,quantity,(SELECT event_id FROM payment_inventory_event WHERE order_id=id) FROM ticket_order WHERE id=?",r,f.order().id());db.update("INSERT INTO issued_ticket(id,order_id,unit,code) VALUES(?,?,1,?)",UUID.randomUUID(),f.order().id(),"P".repeat(43));return null;}));assertEquals(0,count("ticket_issuance",f.order().id()));assertEquals(0,count("issued_ticket",f.order().id()));}
 @Test void immutableEvidenceCannotResetReuseDeleteOrChangeCode(){var f=fixture(1);var t=issue(f).tickets().getFirst();var c=check(f,t);tickets.checkIn(manager,c);for(String q:List.of("UPDATE issued_ticket SET code='"+"Z".repeat(43)+"' WHERE id='"+t.id()+"'","UPDATE issued_ticket SET state='ACTIVE',version=1,changed_at=NULL,changed_request_id=NULL WHERE id='"+t.id()+"'","DELETE FROM issued_ticket WHERE id='"+t.id()+"'","DELETE FROM ticket_issuance WHERE order_id='"+f.order().id()+"'","UPDATE ticket_admission_command SET action='REVOKE' WHERE request_id='"+c.requestId()+"'","DELETE FROM ticket_admission_audit WHERE request_id='"+c.requestId()+"'"))assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.execute(q));}
 @Test void roleChangesAndBoundsAreRechecked(){var f=fixture(1);var t=issue(f).tickets().getFirst();String actor="temporary-ticket-manager-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),actor,"unused","MANAGER");db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",actor);problem(403,()->tickets.checkIn(actor,check(f,t)));assertEquals(1,tickets.list(actor,f.session(),1,20).total());problem(400,()->tickets.list(viewer,f.session(),1,21));problem(400,()->tickets.audit(viewer,t.id(),0,12));}
 @Test void httpIdentityCsrfAndStrictBodyAreEnforced()throws Exception{var f=fixture(1);var t=issue(f).tickets().getFirst();String path="/api/customer/orders/"+f.order().id()+"/tickets";mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).cookie(new Cookie("TICKET_CUSTOMER_SESSION",f.token())).header("X-Expected-Customer-ID",UUID.randomUUID())).andExpect(status().isUnauthorized());mvc.perform(post(path).cookie(new Cookie("TICKET_CUSTOMER_SESSION",f.token())).contentType("application/json").content(json.writeValueAsString(new Issue(UUID.randomUUID(),3)))).andExpect(status().isForbidden());var tokenResult=mvc.perform(get("/api/customer/auth/csrf")).andReturn();var token=json.readTree(tokenResult.getResponse().getContentAsString());mvc.perform(post(path).cookie(new Cookie("TICKET_CUSTOMER_SESSION",f.token()),tokenResult.getResponse().getCookie("TICKET_CUSTOMER_CSRF")).header(token.get("headerName").asText(),token.get("token").asText()).contentType("application/json").content("{\"requestId\":\""+UUID.randomUUID()+"\",\"expectedVersion\":3,\"owner\":\"spoof\"}")).andExpect(status().isBadRequest());var staff=user(manager).authorities(()->"CATALOG_READ",()->"CATALOG_WRITE");mvc.perform(post("/api/admin/admissions/check-ins").with(staff).contentType("application/json").content(json.writeValueAsString(check(f,t)))).andExpect(status().isForbidden());mvc.perform(post("/api/admin/admissions/check-ins").with(staff).with(csrf()).header("X-Expected-Staff-Username",viewer).contentType("application/json").content(json.writeValueAsString(check(f,t)))).andExpect(status().isUnauthorized());}
 @Test void customerSessionDeadlineRecheckedAfterActualOrderLock()throws Exception{var f=fixture(1);pay(f,"SUCCESS");var end=db.queryForObject("UPDATE customer_session SET expires_at=clock_timestamp()+interval '6 seconds' WHERE token_hash=? RETURNING expires_at",OffsetDateTime.class,f.customer().sessionHash());try(var pool=Executors.newSingleThreadExecutor()){var task=new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM ticket_order WHERE id=? FOR UPDATE",UUID.class,f.order().id());var future=pool.submit(()->tickets.issue(f.customer(),f.order().id(),new Issue(UUID.randomUUID(),3)));for(int i=0;i<100;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE wait_event_type='Lock' AND datname=current_database() AND query LIKE '%SELECT * FROM ticket_order WHERE id=%FOR UPDATE%'",Integer.class)>0)break;try{Thread.sleep(30);}catch(Exception e){throw new AssertionError(e);}if(i==99)fail("Actual order lock wait required");}try{Thread.sleep(Math.max(1,Duration.between(OffsetDateTime.now(),end).toMillis()+100));}catch(Exception e){throw new AssertionError(e);}s.setRollbackOnly();return future;});var error=assertThrows(ExecutionException.class,()->task.get(10,TimeUnit.SECONDS));assertInstanceOf(Problem.class,error.getCause());assertEquals(401,((Problem)error.getCause()).status);}assertEquals(0,count("ticket_issuance",f.order().id()));}

}
